fn solve(input: Vec<char>) -> i8 {
    // We assume input.len() == 3 and each char is either 'R' or 'S'.
    let mut max_consecutive: i8 = 0;
    let mut current_count: i8 = 0;

    for &day in &input {
        if day == 'R' {
            current_count += 1;
            if current_count > max_consecutive {
                max_consecutive = current_count;
            }
        } else {
            // Reset the running count when it's not rainy
            current_count = 0;
        }
    }

    max_consecutive
}

fn main() {
    let cases = vec![
        vec!['S', 'S', 'S'], // no rainy days -> 0
        vec!['R', 'S', 'R'], // isolated rainy days -> 1
        vec!['R', 'R', 'S'], // two consecutive rainy days -> 2
        vec!['R', 'R', 'R'], // all rainy days -> 3
        vec!['S', 'R', 'R'], // two consecutive rainy days -> 2
    ];

    for input in cases {
        println!("{:?} -> {}", input, solve(input));
    }
}